"""
Sequential Executor Policy (Internal)

Evaluates exit conditions for the Sequential Executor. Receives the current
data and exit conditions, returns whether the loop should exit.

@extension_type: policy

@input_ports:
  - port_name: input
    port_type: in
    artifact_type_input: json

@policy_states:
  - continue
  - exit
"""

ENTRY_CLASS = "SequentialExecutorPolicy"

import perceivo


class SequentialExecutorPolicy(perceivo.primitives.Policy):

    async def run(self, input: perceivo.primitives.PolicyInput) -> perceivo.primitives.PolicyOutput:
        rd = input.request_data or {}
        data = rd.get("data", {})
        exit_conditions = rd.get("exit_conditions", [])
        iteration = rd.get("iteration", 0)
        max_iterations = rd.get("max_iterations", 10)

        # Check max iterations (safety override)
        if iteration >= max_iterations:
            return perceivo.primitives.PolicyOutput(
                next_state="exit",
                response_data={
                    "should_exit": True,
                    "exit_reason": f"max_iterations ({max_iterations}) reached",
                },
            )

        # Evaluate user-defined exit conditions (ANY match = exit)
        for cond in exit_conditions:
            field = cond.get("field", "")
            operator = cond.get("operator", "equals")
            expected = cond.get("value", "")

            if not field:
                continue

            actual = self._get_field(data, field)

            if self._evaluate(actual, operator, expected):
                reason = f"{field} {operator} {expected} (actual: {actual})"
                perceivo.log.info(f"Exit condition met: {reason}")
                return perceivo.primitives.PolicyOutput(
                    next_state="exit",
                    response_data={
                        "should_exit": True,
                        "exit_reason": reason,
                    },
                )

        return perceivo.primitives.PolicyOutput(
            next_state="continue",
            response_data={
                "should_exit": False,
                "exit_reason": None,
            },
        )

    def _get_field(self, data, field: str):
        """Get a value from data using dot-path."""
        keys = field.split(".")
        current = data
        for key in keys:
            if isinstance(current, dict) and key in current:
                current = current[key]
            else:
                return None
        return current

    def _evaluate(self, actual, operator: str, expected: str) -> bool:
        if operator == "is_null":
            return actual is None
        if operator == "is_not_null":
            return actual is not None
        if actual is None:
            return False

        # Smart cast expected value
        try:
            if "." in expected:
                cast_expected = float(expected)
            else:
                cast_expected = int(expected)
        except (ValueError, TypeError):
            cast_expected = expected

        if operator == "equals":
            return actual == cast_expected or str(actual) == str(expected)
        elif operator == "not_equals":
            return actual != cast_expected and str(actual) != str(expected)
        elif operator == "contains":
            return str(expected) in str(actual)
        elif operator == "greater_than":
            try:
                return float(actual) > float(expected)
            except (TypeError, ValueError):
                return False
        elif operator == "less_than":
            try:
                return float(actual) < float(expected)
            except (TypeError, ValueError):
                return False
        elif operator == "greater_equal":
            try:
                return float(actual) >= float(expected)
            except (TypeError, ValueError):
                return False
        elif operator == "less_equal":
            try:
                return float(actual) <= float(expected)
            except (TypeError, ValueError):
                return False
        return False

