"""
Milvus Tool (Internal)

Vector database operations using the organization's Milvus instance.
Supports collection management, vector insert, and similarity search.

@extension_type: tool

@input_ports:
  - port_name: input
    port_type: in
    artifact_type_input: json
    artifact_type_output: json

@input_parameters:
  - name: operation
    type: select
    label: Operation
    options: [CREATE_COLLECTION, INSERT, SEARCH, DELETE, LIST_COLLECTIONS, DROP_COLLECTION]
    default: SEARCH
    required: true
  - name: collection_name
    type: text
    label: Collection Name
    description: Supports ${variable}.
  - name: dimension
    type: integer
    label: Vector Dimension
    default: 1536
  - name: metric_type
    type: select
    label: Distance Metric
    options: [COSINE, L2, IP]
    default: COSINE
  - name: top_k
    type: integer
    label: Top K Results
    default: 10
  - name: filter_expr
    type: text
    label: Filter Expression
"""

ENTRY_CLASS = "MilvusTool"

import perceivo
import json as _json
import re as _re


def _resolve_path(data, path):
    """Traverse a dot-notation path in a nested dict."""
    if not data or not path:
        return None
    parts = path.split(".")
    current = data
    for part in parts:
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return None
    return current


def _resolve_vars(template: str, data: dict) -> str:
    def replacer(match):
        var_path = match.group(1)
        val = _resolve_path(data, var_path)
        return str(val) if val is not None else match.group(0)
    return _re.sub(r'\$\{([\w.]+)\}', replacer, template)


class MilvusTool(perceivo.primitives.Tool):

    async def run(self, input: perceivo.primitives.ToolInput) -> perceivo.primitives.ToolOutput:
        rd = input.request_data or {}

        def _cfg(name, default=""):
            configured = str(perceivo.params.get(name, default))
            if "${" in configured:
                return _resolve_vars(configured, rd)
            return configured

        operation = _cfg("operation", "SEARCH").upper()
        collection_name = _cfg("collection_name", "")
        dimension = int(_cfg("dimension", "1536"))
        metric_type = _cfg("metric_type", "COSINE")
        top_k = int(_cfg("top_k", "10"))
        filter_expr = _cfg("filter_expr", "")

        if not collection_name and operation != "LIST_COLLECTIONS":
            return self._result(False, operation, error="collection_name is required")

        try:
            milvus = await perceivo.cluster.milvus.connect()
        except Exception as e:
            perceivo.log.error(f"Milvus connection failed: {e}")
            return self._result(False, operation, error=f"Milvus not available: {e}")

        try:
            if operation == "CREATE_COLLECTION":
                from pymilvus import CollectionSchema, FieldSchema, DataType
                fields = [
                    FieldSchema(name="id", dtype=DataType.INT64, is_primary=True, auto_id=True),
                    FieldSchema(name="vector", dtype=DataType.FLOAT_VECTOR, dim=dimension),
                    FieldSchema(name="text", dtype=DataType.VARCHAR, max_length=65535),
                    FieldSchema(name="metadata", dtype=DataType.JSON),
                ]
                schema = CollectionSchema(fields=fields)
                index_params = milvus.prepare_index_params()
                index_params.add_index(
                    field_name="vector", metric_type=metric_type, index_type="AUTOINDEX")
                milvus.create_collection(
                    collection_name=collection_name,
                    schema=schema,
                    index_params=index_params,
                )
                perceivo.log.info(
                    f"Milvus CREATE_COLLECTION {collection_name}",
                    dimension=dimension,
                    metric=metric_type,
                )
                return self._result(True, operation, collection=collection_name)

            elif operation == "INSERT":
                vectors = rd.get("vectors", [])
                texts = rd.get("texts", [])
                metadata_list = rd.get("metadata", [])
                if not vectors:
                    return self._result(False, operation, error="vectors required in request_data")
                data_rows = []
                for i, vec in enumerate(vectors):
                    data_rows.append({
                        "vector": vec,
                        "text": texts[i] if i < len(texts) else "",
                        "metadata": metadata_list[i] if i < len(metadata_list) else {},
                    })
                milvus.insert(collection_name=collection_name, data=data_rows)
                perceivo.log.info(f"Milvus INSERT {collection_name}", count=len(vectors))
                return self._result(True, operation, collection=collection_name, count=len(vectors))

            elif operation == "SEARCH":
                query_vectors = rd.get("query_vectors", [])
                if not query_vectors:
                    return self._result(False, operation, error="query_vectors required in request_data")
                kwargs = {
                    "collection_name": collection_name,
                    "data": query_vectors,
                    "limit": top_k,
                    "output_fields": ["text", "metadata"],
                    "search_params": {"metric_type": metric_type},
                }
                if filter_expr:
                    kwargs["filter"] = filter_expr
                results = milvus.search(**kwargs)
                matches = []
                for hits in results:
                    query_matches = []
                    for hit in hits:
                        query_matches.append({
                            "id": hit["id"],
                            "distance": hit["distance"],
                            "text": hit["entity"].get("text", ""),
                            "metadata": hit["entity"].get("metadata", {}),
                        })
                    matches.append(query_matches)
                perceivo.log.info(
                    f"Milvus SEARCH {collection_name}",
                    queries=len(query_vectors),
                    top_k=top_k,
                )
                return self._result(True, operation, collection=collection_name,
                                    matches=matches, count=len(matches))

            elif operation == "DELETE":
                ids = rd.get("ids", [])
                filter_del = rd.get("filter", filter_expr)
                if ids:
                    milvus.delete(collection_name=collection_name, ids=ids)
                elif filter_del:
                    milvus.delete(collection_name=collection_name, filter=filter_del)
                else:
                    return self._result(False, operation, error="ids or filter required")
                perceivo.log.info(f"Milvus DELETE {collection_name}")
                return self._result(True, operation, collection=collection_name, deleted=True)

            elif operation == "LIST_COLLECTIONS":
                collections = milvus.list_collections()
                perceivo.log.info("Milvus LIST_COLLECTIONS", count=len(collections))
                return self._result(True, operation, collections=collections,
                                    count=len(collections))

            elif operation == "DROP_COLLECTION":
                milvus.drop_collection(collection_name=collection_name)
                perceivo.log.info(f"Milvus DROP_COLLECTION {collection_name}")
                return self._result(True, operation, collection=collection_name, dropped=True)

            else:
                return self._result(False, operation, error=f"Unknown operation: {operation}")

        except Exception as e:
            perceivo.log.error(f"Milvus {operation} failed: {e}")
            return self._result(False, operation, error=str(e))

    def _result(self, success, operation, collection="", matches=None,
                collections=None, count=None, deleted=None, dropped=None, error=None):
        data = {"success": success, "operation": operation}
        if collection:
            data["collection"] = collection
        if matches is not None:
            data["matches"] = matches
        if collections is not None:
            data["collections"] = collections
        if count is not None:
            data["count"] = count
        if deleted is not None:
            data["deleted"] = deleted
        if dropped is not None:
            data["dropped"] = dropped
        if error:
            data["error"] = error
        return perceivo.primitives.ToolOutput(
            artifact=perceivo.primitives.Artifact(
                type=perceivo.primitives.ArtifactType.JSON, data=data, mime_type="application/json"),
            response_data=data,
        )

